template:
discovery.dockerswarm "${1:default}" {
  authorization {
    $0
  }
  basic_auth {
    $0
  }
  filter {
    name = "${2}"
    values = "${3}"
  }
  oauth2 {
  }
  tls_config {
    $0
  }

  // Exported fields:
  // - targets (list(map(string))): The set of targets discovered from Swarm.
}
